using Grpc.Core;
using Grpc.Net.Client;

// Service client types are generated by buf into gen/ — run `buf generate` first.
// After generation, the following namespaces will be available:
//   Authzed.Api.V1 — containing PermissionsService, SchemaService, WatchService, ExperimentalService
using Authzed.Api.V1;

namespace Authzed.Api.SpiceDB.Proto;

/// <summary>
/// SpiceDBProtoClient wraps all generated gRPC service clients for SpiceDB.
/// It handles channel creation, TLS configuration, and bearer token injection.
/// </summary>
public sealed class SpiceDBProtoClient : IDisposable
{
    private readonly GrpcChannel _channel;

    /// <summary>gRPC client for the SpiceDB Permissions service.</summary>
    public PermissionsService.PermissionsServiceClient Permissions { get; }

    /// <summary>gRPC client for the SpiceDB Schema service.</summary>
    public SchemaService.SchemaServiceClient Schema { get; }

    /// <summary>gRPC client for the SpiceDB Watch service.</summary>
    public WatchService.WatchServiceClient Watch { get; }

    /// <summary>gRPC client for the SpiceDB Experimental service.</summary>
    public ExperimentalService.ExperimentalServiceClient Experimental { get; }

    /// <summary>
    /// Creates a new SpiceDB proto client connected to the given endpoint,
    /// authenticated with the given bearer token.
    /// </summary>
    /// <param name="endpoint">The gRPC endpoint (e.g. "grpc.authzed.com:443").</param>
    /// <param name="token">Bearer token for authentication.</param>
    /// <param name="insecure">If true, uses plaintext (no TLS). For testing only.</param>
    public SpiceDBProtoClient(string endpoint, string token, bool insecure = false)
    {
        var scheme = insecure ? "http" : "https";
        var address = $"{scheme}://{endpoint}";

        var callCredentials = CallCredentials.FromInterceptor((_, metadata) =>
        {
            metadata.Add("authorization", $"Bearer {token}");
            return Task.CompletedTask;
        });

        var channelCredentials = insecure
            ? ChannelCredentials.Insecure
            : ChannelCredentials.SecureSsl;

        // Compose channel credentials with call credentials for secure channels.
        // For insecure channels, we add the bearer token via a separate interceptor
        // since CompositeChannelCredentials requires secure transport.
        GrpcChannelOptions options;
        if (insecure)
        {
            options = new GrpcChannelOptions
            {
                Credentials = ChannelCredentials.Insecure,
            };
        }
        else
        {
            var compositeCredentials = ChannelCredentials.Create(channelCredentials, callCredentials);
            options = new GrpcChannelOptions
            {
                Credentials = compositeCredentials,
            };
        }

        _channel = GrpcChannel.ForAddress(address, options);

        // For insecure channels, use CallInvoker with headers to inject the token.
        var invoker = _channel.CreateCallInvoker();
        if (insecure)
        {
            invoker = invoker.Intercept(metadata =>
            {
                metadata.Add("authorization", $"Bearer {token}");
                return metadata;
            });
        }

        Permissions = new PermissionsService.PermissionsServiceClient(invoker);
        Schema = new SchemaService.SchemaServiceClient(invoker);
        Watch = new WatchService.WatchServiceClient(invoker);
        Experimental = new ExperimentalService.ExperimentalServiceClient(invoker);
    }

    /// <summary>
    /// Disposes the underlying gRPC channel.
    /// </summary>
    public void Dispose()
    {
        _channel.Dispose();
    }
}
